import java.util.Collections;
import java.util.List;

class Box<T> {
    private T value;

    Box(T value) { this.value = value; }

    T get() { return value; }

    T replace(T newValue) {
        T old = value;
        value = newValue;
        return old;
    }

    // <T> before the return type
    static <T> T firstOrNull(List<T> items) {
        return items.isEmpty() ? null : items.get(0);
    }

    static void use() {
        Box<String> box = new Box<>("EUR");            // diamond infers <String>
        Box raw = new Box("EUR");                        // raw type: checks off
        List<String> none = Collections.<String>emptyList();
        List<Integer> ints = List.of(1, 2);               // no List<int>
    }
}

