class Box<T>(var value: T) {
    fun replace(newValue: T): T {
        val old = value
        value = newValue
        return old
    }
}

// <T> before the function name
fun <T> firstOrNull(items: List<T>): T? =
    if (items.isEmpty()) null else items[0]

fun use() {
    val box = Box("EUR")                  // Box<String>, no diamond needed
    // there is no raw Box: Box without <...> must be inferable or it does not compile
    val none = emptyList<String>()
    val ints: List<Int> = listOf(1, 2)     // Int works; stored as java.lang.Integer
}

